                    'example' => "library(dplyr)\n\ndata <- data.frame(\n  produk = c('Kopi', 'Teh', 'Kopi', 'Susu'),\n  jumlah = c(12, 8, 5, 10)\n)\n\nringkasan <- data %>%\n  group_by(produk) %>%\n  summarise(total = sum(jumlah)) %>%\n  arrange(desc(total))\n\nprint(ringkasan)\n\n# Output:\n# produk   total\n# Kopi     17\n# Susu     10\n# Teh       8",
