                    'example' => "library(ggplot2)\n\ndata <- data.frame(\n  bulan = c('Jan', 'Feb', 'Mar', 'Apr'),\n  penjualan = c(120, 150, 130, 170)\n)\n\nggplot(data, aes(x = bulan, y = penjualan, group = 1)) +\n  geom_line() +\n  geom_point() +\n  labs(title = 'Tren Penjualan per Bulan',\n       x = 'Bulan', y = 'Jumlah Terjual')\n\n# Output: grafik garis dengan titik pada\n# setiap bulan, lengkap dengan judul dan\n# label sumbu yang jelas",
